window.__ModuleLoader__.load({
	id: "dsh-chat-character",
	factory: (require) => {
		const module = { exports: {} };
		const IMG_ID = "dsh-chat-character-img";
		const DATA_URI = "data:image/png;base64," + "";
		// 容器内左下角挂载：用后缀匹配抗哈希变化（哈希前缀每次构建都会变，_centerCol 后缀稳定）
		const TARGET = '[class$="_centerCol"]';
		let observer = null;
		let lastStrip = 0;

		function mount() {
			const col = document.querySelector(TARGET);
			if (!col) return;
			if (!document.getElementById(IMG_ID)) {
				const img = document.createElement("img");
				img.id = IMG_ID;
				img.src = DATA_URI;
				img.alt = "";
				img.setAttribute("aria-hidden", "true");
				Object.assign(img.style, {
					position: "absolute", left: "0px", bottom: "0px",
					width: "170px", maxHeight: "45%", objectFit: "contain",
					objectPosition: "left bottom", pointerEvents: "none",
					zIndex: "0", opacity: "0.96", userSelect: "none"
				});
				if (getComputedStyle(col).position === "static") col.style.position = "relative";
				col.appendChild(img);
			}
			const now = Date.now();
			if (now - lastStrip > 500) { lastStrip = now; stripGradients(col); }
		}

		// 清掉左下角区域的底部渐隐遮罩，避免压住立绘
		function stripGradients(col) {
			const cr = col.getBoundingClientRect();
			const zone = cr.top + cr.height * 0.55;
			for (const el of col.querySelectorAll("*")) {
				const r = el.getBoundingClientRect();
				if (r.height === 0 || r.top < zone || r.width < cr.width * 0.3) continue;
				const bi = getComputedStyle(el).backgroundImage;
				if (bi && bi.includes("gradient")) el.style.backgroundImage = "none";
			}
		}

		function start() {
			mount();
			observer = new MutationObserver(() => mount());
			observer.observe(document.documentElement, { childList: true, subtree: true });
		}

		function apply() {
			if (document.readyState === "loading") {
				document.addEventListener("DOMContentLoaded", start, { once: true });
			} else {
				start();
			}
		}

		module.exports.apply = apply;
		module.exports.inject = [];
		return module.exports;
	}
});
